mapper.insert:
INSERT INTO EMAIL_VERIFICATION (
	ID, EMAIL, PURPOSE, CODE_HASH, EXPIRES_AT
) VALUES (
	nextval('SEQ_EMAIL_VERIFICATION'),
	#{email}, #{purpose}, #{codeHash}, #{expiresAt}
)

mapper.select:
SELECT ID, EMAIL, PURPOSE, CODE_HASH, EXPIRES_AT, CONSUMED, ATTEMPTS, CREATED_AT
FROM EMAIL_VERIFICATION
WHERE EMAIL = #{email}
  AND PURPOSE = #{purpose}
ORDER BY ID DESC
LIMIT 1

mapper.update:
UPDATE EMAIL_VERIFICATION
SET CONSUMED = 'Y'
WHERE EMAIL = #{email}
  AND PURPOSE = #{purpose}
  AND CONSUMED = 'N'

UPDATE EMAIL_VERIFICATION
SET ATTEMPTS = ATTEMPTS + 1
WHERE ID = #{id}

UPDATE EMAIL_VERIFICATION
SET CONSUMED = 'Y'
WHERE ID = #{id}
